// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.bulk;

import static java.nio.charset.StandardCharsets.UTF_8;
import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.IOException;
import java.util.ArrayList;
import java.util.HexFormat;
import java.util.List;

import org.eclipse.rdf4j.model.Literal;
import org.eclipse.rdf4j.model.vocabulary.XSD;
import org.eclipse.rdf4j.rio.RDFFormat;
import org.junit.jupiter.api.Test;

/** Exhaustive finite-domain check of raw UTF-8 and numeric escape decoding inside a literal. */
class FastNQuadsUnicodeScalarTest {

	@Test
	void roundTripsEveryUnicodeScalarThroughRawAndEscapedLiteralPaths() throws IOException {
		FastNTriplesParser parser = new FastNTriplesParser(RDFFormat.NQUADS, () -> false);
		long checked = 0;
		for (int first = 0; first <= Character.MAX_CODE_POINT; first += 512) {
			StringBuilder source = new StringBuilder(40_000);
			List<String> expected = new ArrayList<>(512);
			for (int codePoint = first; codePoint <= Math.min(Character.MAX_CODE_POINT, first + 511); codePoint++) {
				if (codePoint >= Character.MIN_SURROGATE && codePoint <= Character.MAX_SURROGATE) {
					continue;
				}
				expected.add("a" + new String(Character.toChars(codePoint)) + "z");
				source.append("<urn:s><urn:p>\"a");
				switch (codePoint) {
				case '"' -> source.append("\\\"");
				case '\\' -> source.append("\\\\");
				case '\n' -> source.append("\\n");
				case '\r' -> source.append("\\r");
				default -> source.appendCodePoint(codePoint);
				}
				source.append("z\".\n<urn:s><urn:p>\"a\\U")
						.append(HexFormat.of().toHexDigits(codePoint))
						.append("z\".\n");
			}
			byte[] bytes = source.toString().getBytes(UTF_8);
			int[] index = { 0 };
			long statements = parser.parseBlock(bytes, 0, bytes.length, 1L, (s, p, o, g) -> {
				Literal literal = (Literal) CanonicalTermCodec.decode(o);
				assertEquals(expected.get(index[0]++ / 2), literal.getLabel());
				assertEquals(XSD.STRING, literal.getDatatype());
				assertEquals(null, g);
			});
			assertEquals(expected.size() * 2L, statements);
			assertEquals(expected.size() * 2, index[0]);
			checked += expected.size();
		}
		assertEquals(1_112_064L, checked);
		System.out.println("Unicode scalar audit: 1,112,064 scalar values; 2,224,128 decoded literals; all exact.");
	}
}
